import GBNF from 'gbnf';

test('collect', () => {
  const cases: [string, string, string][] = JSON.parse(readFileSync('/tmp/cases.json', 'utf-8'));
  const out: unknown[] = [];
  for (const [, grammar, inp] of cases) {
    const steps: unknown[] = [];
    try {
      let state = GBNF(grammar);
      steps.push([...state]);
      for (const ch of inp) {
        state = state.add(ch);
        steps.push([...state]);
      }
      steps.push((state as any).graph.print());
    } catch (e) {
      steps.push({ error: (e as Error).name, message: (e as Error).message });
    }
    out.push(steps);
  }
  writeFileSync('/tmp/out_ts.json', JSON.stringify(out));
});
EOF
vitest run --config vitest.config.smoke.ts 2>&1 | tail -20

